(function () {
    var XXGetHistoryCommand;

    XXGetHistoryCommand = (function () {
        function XXGetHistoryCommand() {
        }

        XXGetHistoryCommand.prototype.execute = function (controller) {
            cc.PopupController.getInstance().showBusy();
            // Subdomain theo gameId hiện tại: 113 → xocdiatl, mặc định → xocdia
            var gameId = cc.RoomController.getInstance().getGameId();
            var subdomain = (gameId == cc.GameId.XOCDIA) ? cc.SubdomainName.XOC_DIA_TL : cc.SubdomainName.XOC_XOC;
            var roomId = cc.RoomController.getInstance().getRoomId() || 0;
            let type = this.type || cc.XXController.getInstance().getTypeHistory();
            if (type !== "history") {
                var url = 'api/XocDia/GetJackpotHistory?roomId=' + roomId;
                cc.PopupController.getInstance().showBusy();
                return cc.ServerConnector.getInstance().sendRequest(subdomain, url, function (response) {
                    cc.PopupController.getInstance().hideBusy();
                    try {
                        var obj = JSON.parse(response);
                        return controller.onXXGetHistoryJPResponse(obj);
                    } catch (e) {
                        console.warn('JackpotHistory parse err', e);
                        return controller.onXXGetHistoryJPResponse({ list: [] });
                    }
                });
            } else {
                var url = 'api/XocDia/GetHistory';
                return cc.ServerConnector.getInstance().sendRequest(subdomain, url, function (response) {
                    console.log('history response: ' + response);
                    cc.PopupController.getInstance().hideBusy();
                    var obj = JSON.parse(response);
                    return controller.onXXGetHistoryResponse(obj);
                });
            }
        };

        XXGetHistoryCommand.prototype.getName = function () {
            return 'XXGetHistoryCommand';
        };

        return XXGetHistoryCommand;

    })();

    cc.XXGetHistoryCommand = XXGetHistoryCommand;

}).call(this);